import * as T from 'three';import {box,cylinder,tree,person,sign,mat,vehicle} from './models.js';
import {createGarage} from './garage.js';
export const XS=[-100,-40,40,100],ZS=[-85,-25,45,105];
let seed=124;const rnd=()=>((seed=(seed*1664525+1013904223)>>>0)/4294967296);
function roof(g,w,d,height,color){const shape=new T.Shape();shape.moveTo(-w/2,0);shape.lineTo(0,height);shape.lineTo(w/2,0);shape.closePath();const mesh=new T.Mesh(new T.ExtrudeGeometry(shape,{depth:d,bevelEnabled:false}),mat(color));mesh.position.set(0,0,-d/2);mesh.castShadow=true;g.add(mesh);return mesh;}
function house(parent,x,z,w,d,floors=2,color='#d6cdb7',store=null){const g=new T.Group();g.position.set(x,0,z);parent.add(g);const h=floors*3.2;box(g,w+.8,.6,d+.8,'#a6a599',0,.3,0);box(g,w,h,d,color,0,h/2+.6,0);box(g,w+.4,.25,d+.4,'#b4b2a6',0,h+.7,0);const rg=new T.Group();rg.position.y=h+.83;g.add(rg);roof(rg,w+1,d+1,2.8,'#6c7479');box(g,1.2,2,1,'#ac8a77',w*.25,h+2.7,-d*.15);for(let level=0;level<floors;level++){for(let col=0;col<Math.max(2,Math.floor(w/4));col++){const wx=-w/2+2+col*(w-4)/Math.max(1,Math.floor(w/4)-1),yy=2+level*3.2;box(g,1.5,1.8,.14,'#eae5d5',wx,yy,d/2+.06);box(g,1.25,1.55,.17,'#526f75',wx,yy,d/2+.15);box(g,.06,1.55,.04,'#d7d8cd',wx,yy,d/2+.25);box(g,1.25,.07,.04,'#d7d8cd',wx,yy,d/2+.25);if(level>0)box(g,1.8,.12,.5,'#aaa99b',wx,yy-.95,d/2+.22);}}
for(const side of[-1,1])for(let level=0;level<floors;level++){for(let k=0;k<2;k++){box(g,.12,1.5,1.25,'#4c666f',side*(w/2+.04),2+level*3.2,-d*.23+k*d*.46);}}if(store){box(g,w-.7,2.35,.2,'#3e626c',0,1.9,d/2+.1);box(g,w+.15,.4,2.3,store.color,0,3.5,d/2+.75);sign(g,store.text,w-.4,.65,0,4,d/2+.23,store.color,'#fff4dc');for(let i=0;i<3;i++)box(g,.12,2.1,.23,'#ece5d2',-w/3+i*w/3,1.7,d/2+.25);}else{box(g,1.3,2.25,.2,'#556762',0,1.6,d/2+.15);box(g,1.7,.2,.8,'#d2cab9',0,.7,d/2+.35);}g.userData={building:true,width:w,depth:d,height:h,street:[x,ZS.reduce((a,b)=>Math.abs(b-z)<Math.abs(a-z)?b:a,ZS[0])]};return g;}
export function neighborhood(scene){const root=new T.Group();scene.add(root);box(root,300,1.8,265,'#606f53',0,-1,12);box(root,286,.15,250,'#818e6f',0,-.05,12);const asphalt=mat('#555d62');const curb='#c3c7bf',pave='#aeb4ab';for(const x of XS){box(root,22,.18,230,pave,x,.1,10);box(root,14,.2,232,asphalt,x,.2,10);for(const side of[-1,1])box(root,.28,.3,230,curb,x+side*7.1,.28,10);for(let z=-100;z<126;z+=8){if(ZS.some(v=>Math.abs(v-z)<10))continue;box(root,.13,.025,3,'#e5dfbe',x,.315,z);}}
for(const z of ZS){box(root,250,.18,22,pave,0,.1,z);box(root,252,.22,14,asphalt,0,.21,z);for(const side of[-1,1])box(root,250,.3,.28,curb,0,.28,z+side*7.1);for(let x=-122;x<124;x+=8){if(XS.some(v=>Math.abs(v-x)<10))continue;box(root,3,.025,.13,'#e5dfbe',x,.335,z);}}
for(const x of XS)for(const z of ZS){box(root,16,.06,16,asphalt,x,.29,z);for(const k of[-1,1]){for(let j=-3;j<=3;j++){box(root,.6,.025,3.1,'#d9ddcf',x+j*1.35,.34,z+k*10);box(root,3.1,.025,.6,'#d9ddcf',x+k*10,.34,z+j*1.35);}}}
// Îlots urbains, jardins et espaces publics.
const buildings=[];const palette=['#dad0b6','#bdbbab','#d3b99d','#dfd6c5','#bfc6bc'];
for(const x of[-119,-71,69,119])for(const z of[-106,-57,11,76,125]){if(x===-71&&z===76)continue;const w=x===-71?20:x===69?21:14,d=z===11?25:19;const b=house(root,x,z,w,d,1+Math.floor(rnd()*3),palette[Math.floor(rnd()*palette.length)]);if(x>0&&rnd()>.5)b.rotation.y=Math.PI;buildings.push(b);}
const hospital=buildings.find(b=>b.position.x===119&&b.position.z===-106);if(hospital){hospital.rotation.y=0;sign(hospital,'CH  •  URGENCES',13,.9,0,4,10,'#477581','#f4f0db');}
const fireBuilding=house(root,5,14,24,27,3,'#d2c4a9',{text:'BOULANGERIE  •  DES TILLEULS',color:'#426b68'});buildings.push(fireBuilding);house(root,-18,12,15,23,2,'#dec5a5',{text:'CAFÉ DU QUARTIER',color:'#a65b47'});house(root,18,-56,28,25,3,'#c4c9c0',{text:'PHARMACIE',color:'#507c68'});house(root,-17,-56,24,25,2,'#d8cfb9');house(root,12,-107,30,19,2,'#c9bda9');
// Le square, côté sud du quartier.
box(root,62,.18,35,'#93a16d',0,.15,76);box(root,3,.1,35,'#d0c6a5',-4,.3,76);box(root,62,.1,3,'#d0c6a5',0,.3,76);for(const [x,z]of[[-22,64],[18,66],[-22,88],[22,88],[5,88]])tree(root,x,z,1.4,Math.floor(rnd()*4));cylinder(root,3.3,3.5,.5,'#b6b7a7',13,.55,76,28);cylinder(root,2.9,2.9,.1,'#598d96',13,.83,76,28);cylinder(root,.35,.55,1.4,'#babdae',13,1.2,76,12);for(const x of[-16,24]){box(root,3,.15,.65,'#775f46',x,.75,72);box(root,3,.65,.15,'#775f46',x,1.1,71.7);box(root,.12,.6,.55,'#4e5751',x-1,.35,72);box(root,.12,.6,.55,'#4e5751',x+1,.35,72);}
// CSP : remise ouverte, trois travées et aire de départ.
const {station,roofs}=createGarage(root);
const lamps=[];for(const x of XS)for(let z=-65;z<111;z+=35){if(ZS.some(k=>Math.abs(k-z)<14))continue;for(const side of[-1,1]){const xx=x+side*9;cylinder(root,.08,.14,6,'#637276',xx,3,z,6);box(root,1.5,.1,.12,'#637276',xx-side*.65,6,z);const head=box(root,.6,.12,.4,new T.MeshStandardMaterial({color:'#f1ddb0',emissive:'#ffe0a0',emissiveIntensity:.15}),xx-side*1.2,5.9,z);lamps.push(head);}}
for(const x of[-112,-88,-52,52,88,112])for(const z of[-73,-38,31,58,94]){if(x<0&&z>58&&x>-90)continue;tree(root,x,z,.8+rnd()*.4,Math.floor(rnd()*4));}
const citizens=[];for(let i=0;i<18;i++){const x=XS[i%4]+(i%2?9:-9),z=-65+rnd()*150;const p=person(root,x,z,['#ad715b','#617d89','#bfaa78','#67705d'][i%4]);citizens.push({model:p,base:z,phase:rnd()*6,direction:i%2?1:-1});}
for(let i=0;i<9;i++){const car=vehicle(root,'VLCG',['#49646e','#a4a59c','#9f674e','#758277'][i%4]);car.scale.setScalar(.88);car.position.set([-100,-40,40,100][i%4]+5.25,0,-63+Math.floor(i/4)*63);car.userData.beacons.forEach(b=>b.visible=false);}
return{root,fireBuilding,buildings,lamps,citizens,station,roofs};}
